    {
      "card_ids": ["C13"],
      "claim": "Compound 7z, which contains the same dimethylisoxazole sulfonamide motif as the query, has human oral availability >80%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Valdecoxib, an isoxazole benzenesulfonamide, has absolute oral bioavailability of 83% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Phosphanilic acid, an aniline with a phosphonic acid group, has only about 4% oral bioavailability in humans; this low value is not transferable because the query has a sulfonamide rather than a charged phosphonic acid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: the query is a sulfanilamide isoxazole, and multiple close sulfonamide analogues show high oral bioavailability (80-100%). The only low-F analogue contains a phosphonic acid group that is absent in the query, so it does not outweigh the strong supportive evidence.",
